// === Tab: mySketch ===
/* 
Hey Friends!
This sketch was created exploring the Tusi Motion Illusion (https://michaelbach.de/ot/mot-Tusi/), researching the illusion in Prof. Shapiro's lab
at American University, trying to find anything "out of the norm" or that "may be unique" for publication. While researching the 
illusion, I became aware I kept coming back to this sketch as modifying it's variables always created something cool and intriguing; Making me 
"inquire" what would happen modifying a few more variables?? What if I added sound to seach moving circle as well?? Hope you all enjoy!

If you like this sketch, feel free to explore other research related sketches here:
3D Tusi Illusion Prototype - https://openprocessing.org/sketch/2695974
Rotating illusion around you - https://openprocessing.org/sketch/2864570

Thoughtspace Exhibit - Interdisciplinary Exhibit of Art & Inquiry Details:
https://www.american.edu/cas/thoughtspace/

*/ 
let oscList = [];
let isPlaying = [];
let centerVec;
let lastDists = [];

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(DEGREES);
  colorMode(RGB);
  OPC.toggle("Randomize", true);
  OPC.slider("background_col", -25, -25, 25, 1);
  OPC.toggle("showCenter", true);
  OPC.slider("bg",  1, 0, 1, 1);
  OPC.toggle("orthographic", true);
  OPC.toggle("showLines", 1, 0, 1, 1);
  OPC.slider("numLines", 19, 1, 500, 1);
  OPC.slider("the_speed", 1, 0, 20);
  OPC.slider("ballOffset", 20, 0, 100, 1);
  OPC.slider("sphereSize", 5, 0, 40, 0.01);
  OPC.slider("yDistance", 0, 0, 1000);
  OPC.slider("lineDist", 600, 0.1, 600, 0.1);
  OPC.slider("colored", 0, 0, 2, 1);
  OPC.toggle("secondTusi", false);
  OPC.toggle("thirdTusi", false);
  OPC.slider("minFreq", 20, 20, 20000, 1);
  OPC.slider("maxFreq", 20000, 20, 20000, 1);
  OPC.slider("freqTime", 200, 0, 1000, .01);
  centerVec = createVector(0, 200, 0);
}
let counter=0
function draw() {
  camera(0, -400, 0, 0, 0, 0, 0, 0, -1);

  if (orthographic) {
    const halfW = width / 2;
    const halfH = height / 2;
    ortho(-halfW, halfW, -halfH, halfH, -10000, 10000);
  } else {
    perspective();
  }
	if(Randomize)
	{
		counter++
		if(counter%round(random(50,200))==0)
		{
			colored=round(random(1))
			//showLines=round(random(1))
			//bg=round(random(1))
			ballOffset=random(100)
			numLines=random(100)
			the_speed=random(.5,7)
			sphereSize=random(3,15)
			maxFreq=random(20000)
			freqTime=random(1000)
			lineDist=random(600,1000)
		}
	}
  colorMode(HSB, 360, 100, 100);
  if(bg) background(70, 20, 50 + background_col);
  orbitControl();

  drawTusi();

  if (secondTusi) {
    push();
    rotateX(90);
    translate(0, -200, -200);
    drawTusi(2);
    pop();
  }

  if (thirdTusi) {
    push();
    rotateX(180);
    rotateZ(90);
    translate(-200, -200, 0);
    drawTusi(3);
    pop();
  }

  if (showCenter) {
    push();
    translate(0, +200, 0);
    fill("red");
    stroke("red");
    sphere(5);
    pop();
  }
}

function drawTusi(tusiNum = 1) {
  stroke(255);
  noFill();

  let centerY = 200;
  let minF = minFreq;
  let maxF = maxFreq;

  if (!oscList[tusiNum]) oscList[tusiNum] = [];
  if (!isPlaying[tusiNum]) isPlaying[tusiNum] = [];
  if (!lastDists[tusiNum]) lastDists[tusiNum] = [];

  for (let i = 0; i < numLines; i++) {
    let t = i / (numLines - 1);
    let angle = t * 360;

    let yPos = centerY - t * yDistance;
    let dirX = cos(angle);
    let dirZ = sin(angle);
    let dir = createVector(dirX, 0, dirZ).normalize().mult(lineDist / 2);

    let startX = -dir.x;
    let startY = yPos;
    let startZ = -dir.z;
    let endX = dir.x;
    let endY = yPos;
    let endZ = dir.z;

    if (showLines) {
      line(startX, startY, startZ, endX, endY, endZ);
    }

    let phaseOffset = i * ballOffset;
    let tAnim = (sin(frameCount * the_speed + phaseOffset) + 1) / 2;

    let ballX = lerp(startX, endX, tAnim);
    let ballY = lerp(startY, endY, tAnim);
    let ballZ = lerp(startZ, endZ, tAnim);

    let ballVec = createVector(ballX, ballY, ballZ);
    let distToCenter = p5.Vector.dist(ballVec, centerVec);


    let freq = map(i, 0, numLines - 1, minF, maxF);

    if (!oscList[tusiNum][i]) {
      let osc = new p5.Oscillator('sine');
      osc.freq(freq);
      osc.amp(0);
      osc.start();
      oscList[tusiNum][i] = osc;
      isPlaying[tusiNum][i] = false;
      lastDists[tusiNum][i] = distToCenter;
    } else {
      oscList[tusiNum][i].freq(freq);
    }

    if (distToCenter < 10 && lastDists[tusiNum][i] >= 10 && !isPlaying[tusiNum][i]) {
      var osc = oscList[tusiNum][i];
      osc.amp(0.5, 0.05);
      isPlaying[tusiNum][i] = true;


      setTimeout(() => {
        osc.amp(0, 0.2);
        isPlaying[tusiNum][i] = false;
      }, freqTime);
    }

    lastDists[tusiNum][i] = distToCenter;

    // Draw sphere
    push();
    translate(ballX, ballY, ballZ);
    noStroke();

    if (colored === 1) {
      colorMode(HSB);
      fill((t * 360) % 360, 255, 255);
      colorMode(RGB);
    } else if (colored === 2) {
      let gray = lerp(255, 0, t);
      fill(gray);
    } else {
      fill(255);
    }

    sphere(sphereSize);
    pop();
  }
}

